const q = $json.query ?? {};
  const headers = $json.headers ?? {};
  const first = (value) => Array.isArray(value) ? value[0] : value;
  const review_id = String(first(q.review_id) ?? '').trim();
  const token = String(first(q.token) ?? '').trim();
  const action = String(first(q.action) ?? '').trim().toUpperCase();
  const actor_login = String(headers['tailscale-user-login'] ?? headers['Tailscale-User-Login'] ?? '').trim().toLowerCase();
  let input_error = '';
  if (!review_id || !token || !action) input_error = 'INCOMPLETE_LINK';
  else if (review_id.length > 200 || token.length > 512) input_error = 'LINK_SIZE_INVALID';
  else if (!['APPROVE', 'EDIT', 'SKIP'].includes(action)) input_error = 'ACTION_INVALID';
  else if (actor_login !== 'dustin.boggess@gmail.com') input_error = 'TAILSCALE_IDENTITY_MISMATCH';
  return [{ json: { review_id, token, action, actor_login, input_error } }];

const row = $json ?? {};
  const request = $('Normalize GET Request').item.json;
  const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
  const shell = (title, body) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#17202a;font:16px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}.wrap{max-width:760px;margin:0 auto;padding:20px}.card{background:#fff;border:1px solid #dfe4ea;border-radius:16px;box-shadow:0 8px 28px #17202a14;padding:24px}h1{font-size:1.55rem;margin:0 0 8px}.muted{color:#5d6d7e}.box{background:#f7f9fa;border:1px solid #e5e9ed;border-radius:10px;padding:14px;margin:14px 0;white-space:pre-wrap}.warning{background:#fff8e6;border-color:#f5d77b}textarea,input{width:100%;font:inherit;border:1px solid #aeb6bf;border-radius:9px;padding:11px}textarea{min-height:210px}.buttons{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:16px}button{border:0;border-radius:10px;padding:13px 10px;font-weight:700;color:#fff;cursor:pointer}.approve{background:#18794e}.edit{background:#1769aa}.skip{background:#657786}img{display:block;max-width:100%;height:auto;border-radius:10px;margin:12px 0}@media(max-width:620px){.wrap{padding:10px}.card{padding:18px}.buttons{grid-template-columns:1fr}}</style></head><body><main class="wrap"><section class="card">${body}</section></main></body></html>`;
  let http_status = 200;
  let response_html = '';
  let event_type = 'LINK_OPENED';
  let result = 'SUCCESS';
  let detail_code = 'CONFIRMATION_PAGE_RENDERED';
  let token_state = 'valid';
  const status_before = String(row.status ?? '').toLowerCase();
  if (request.input_error) {
    http_status = 403; event_type = 'LINK_INVALID'; result = 'REJECTED'; detail_code = request.input_error; token_state = 'invalid';
    response_html = shell('Review link unavailable', '<h1>Review link unavailable</h1><p>This link is invalid or no longer available. Please use the latest review email.</p>');
  } else if (!row.review_id) {
    http_status = 403; event_type = 'LINK_INVALID'; result = 'REJECTED'; detail_code = 'TOKEN_OR_REVIEW_NOT_FOUND'; token_state = 'invalid';
    response_html = shell('Review link unavailable', '<h1>Review link unavailable</h1><p>This link is invalid or no longer available. Please use the latest review email.</p>');
  } else if (String(row.reviewer_email ?? '').trim().toLowerCase() !== request.actor_login) {
    http_status = 403; event_type = 'LINK_INVALID'; result = 'REJECTED'; detail_code = 'REVIEWER_IDENTITY_MISMATCH'; token_state = 'valid';
    response_html = shell('Review link unavailable', '<h1>Review link unavailable</h1><p>This link is not assigned to the current Tailscale identity.</p>');
  } else if (!['pending', 'awaiting_review', 'review_pending'].includes(status_before)) {
    http_status = 409; event_type = 'LINK_REUSE_REJECTED'; result = 'REJECTED'; detail_code = 'REVIEW_NOT_PENDING'; token_state = 'reused';
    response_html = shell('Review already handled', `<h1>Review already handled</h1><p>This review is no longer awaiting a decision.</p><p class="muted">Reference: ${esc(row.review_id)}</p>`);
  } else {
    const expiry = Date.parse(row.expires_at);
    if (!Number.isFinite(expiry) || expiry <= Date.now()) {
      http_status = 410; event_type = 'LINK_EXPIRED'; result = 'REJECTED'; detail_code = 'TOKEN_EXPIRED'; token_state = 'expired';
      response_html = shell('Review link expired', `<h1>Review link expired</h1><p>This approval link has expired. Request a fresh review email to continue.</p><p class="muted">Reference: ${esc(row.review_id)}</p>`);
    } else {
      const source = [row.source_type, row.source_reference].filter(Boolean).map(esc).join(' · ');
      const image = /^https:\/\//i.test(String(row.image_url ?? '')) ? `<img src="${esc(row.image_url)}" alt="Proposed post image">` : '<p class="muted">No image is attached to this draft.</p>';
      const expires = new Date(expiry).toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'medium', timeStyle: 'short' });
      response_html = shell('Review Google Business draft', `<h1>Confirm ${esc(request.action.toLowerCase())}</h1><p class="muted">Reference: ${esc(row.review_id)} · Link expires ${esc(expires)} ET</p><p>The email click expressed intent only. Use a button below to record the final decision.</p><h2>Source</h2><p class="muted">${source || 'Approved business content'}</p><div class="box">${esc(row.source_text)}</div><h2>Proposed wording</h2><form method="post" action="/webhook/fsv-google-review-decision" enctype="application/x-www-form-urlencoded"><input type="hidden" name="review_id" value="${esc(request.review_id)}"><input type="hidden" name="token" value="${esc(request.token)}"><label for="edited_text">Post text</label><textarea id="edited_text" name="edited_text" maxlength="5000">${esc(row.proposed_text)}</textarea>${image}<h2>Google compatibility note</h2><div class="box warning">${esc(row.google_warning)}</div><label for="notes">Decision note (optional)</label><input id="notes" name="notes" maxlength="2000" placeholder="Add context for the audit log"><p class="muted">Approve records the current draft. Edit &amp; Save records the text in the box. Skip closes this review. Nothing on this page publishes to Google.</p><div class="buttons"><button class="approve" type="submit" name="action" value="APPROVE">Approve</button><button class="edit" type="submit" name="action" value="EDIT">Edit &amp; Save</button><button class="skip" type="submit" name="action" value="SKIP">Skip</button></div></form>`);
    }
  }
  return [{ json: {
    review_id: String(row.review_id ?? request.review_id), action: request.action,
    approver: request.actor_login, actor_basis: request.actor_login ? 'TAILSCALE_IDENTITY_HEADER' : '',
    status_before, status_after: status_before, token_state, http_status,
    event_type, result, detail_code, response_html,
  } }];

const requestBody = $json.body ?? {};
  const headers = $json.headers ?? {};
  const first = (value) => Array.isArray(value) ? value[0] : value;
  const review_id = String(first(requestBody.review_id) ?? '').trim();
  const token = String(first(requestBody.token) ?? '').trim();
  const action = String(first(requestBody.action) ?? '').trim().toUpperCase();
  const edited_text = String(first(requestBody.edited_text) ?? '').trim();
  const notes = String(first(requestBody.notes) ?? '').trim();
  const actor_login = String(headers['tailscale-user-login'] ?? headers['Tailscale-User-Login'] ?? '').trim().toLowerCase();
  let input_error = '';
  if (!review_id || !token || !action) input_error = 'FORM_INCOMPLETE';
  else if (review_id.length > 200 || token.length > 512 || edited_text.length > 5000 || notes.length > 2000) input_error = 'FORM_SIZE_INVALID';
  else if (!['APPROVE', 'EDIT', 'SKIP'].includes(action)) input_error = 'ACTION_INVALID';
  else if (action === 'EDIT' && !edited_text) input_error = 'EDIT_TEXT_EMPTY';
  else if (actor_login !== 'dustin.boggess@gmail.com') input_error = 'TAILSCALE_IDENTITY_MISMATCH';
  return [{ json: { review_id, token, action, edited_text, notes, actor_login, input_error } }];

const row = $json ?? {};
  const request = $('Normalize POST Request').item.json;
  const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
  const errorPage = (title, message, reference = '') => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>body{margin:0;background:#f4f6f8;color:#17202a;font:16px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}.card{max-width:680px;margin:30px auto;background:#fff;border:1px solid #dfe4ea;border-radius:16px;padding:24px;box-shadow:0 8px 28px #17202a14}.muted{color:#5d6d7e}</style></head><body><main class="card"><h1>${esc(title)}</h1><p>${esc(message)}</p>${reference ? `<p class="muted">Reference: ${esc(reference)}</p>` : ''}<p>No content was published.</p></main></body></html>`;
  let can_update = true;
  let http_status = 200;
  let response_html = '';
  let event_type = 'DECISION_SUBMITTED';
  let result = 'ATTEMPTED';
  let detail_code = 'VALID_DECISION_SUBMISSION';
  let token_state = 'valid';
  const original_status = String(row.status ?? '').toLowerCase();
  if (request.input_error) {
    can_update = false; http_status = 400; event_type = 'DECISION_INVALID'; result = 'REJECTED'; detail_code = request.input_error; token_state = 'invalid';
    response_html = errorPage('Decision not recorded', 'The decision request is invalid. Please use the latest review email.');
  } else if (!row.review_id) {
    can_update = false; http_status = 403; event_type = 'DECISION_INVALID_TOKEN'; result = 'REJECTED'; detail_code = 'TOKEN_OR_REVIEW_NOT_FOUND'; token_state = 'invalid';
    response_html = errorPage('Decision link unavailable', 'This link is invalid or no longer available. Please use the latest review email.');
  } else if (String(row.reviewer_email ?? '').trim().toLowerCase() !== request.actor_login) {
    can_update = false; http_status = 403; event_type = 'DECISION_INVALID'; result = 'REJECTED'; detail_code = 'REVIEWER_IDENTITY_MISMATCH'; token_state = 'valid';
    response_html = errorPage('Decision not recorded', 'This review is not assigned to the current Tailscale identity.', row.review_id);
  } else if (!['pending', 'awaiting_review', 'review_pending'].includes(original_status)) {
    can_update = false; http_status = 409; event_type = 'TOKEN_REUSE_REJECTED'; result = 'REJECTED'; detail_code = 'REVIEW_NOT_PENDING'; token_state = 'reused';
    response_html = errorPage('Review already handled', 'This review is no longer awaiting a decision.', row.review_id);
  } else {
    const expiry = Date.parse(row.expires_at);
    if (!Number.isFinite(expiry) || expiry <= Date.now()) {
      can_update = false; http_status = 410; event_type = 'DECISION_EXPIRED'; result = 'REJECTED'; detail_code = 'TOKEN_EXPIRED'; token_state = 'expired';
      response_html = errorPage('Decision link expired', 'This approval link has expired. Request a fresh review email to continue.', row.review_id);
    }
  }
  const next_status = request.action === 'APPROVE' ? 'approved_not_published' : request.action === 'EDIT' ? 'edited_not_published' : 'skipped';
  const new_proposed_text = request.action === 'EDIT' ? request.edited_text : String(row.proposed_text ?? '');
  return [{ json: {
    ...row, can_update, http_status, response_html, original_status,
    decision: request.action, decision_notes: request.notes, next_status, new_proposed_text,
    decided_at: new Date().toISOString(), approver: request.actor_login,
    actor_basis: request.actor_login ? 'TAILSCALE_IDENTITY_HEADER' : '',
    publish_result: 'not_published', event_type, result, detail_code, token_state,
  } }];

const updated = $json ?? {};
  const prepared = $('Prepare Decision Update').item.json;
  const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
  const success = Boolean(updated.review_id);
  const http_status = success ? 200 : 409;
  const title = success ? 'Decision recorded' : 'Review already handled';
  const message = success ? `${prepared.decision} was recorded for ${prepared.review_id}.` : 'Another submission already handled this review. Your duplicate submission was not applied.';
  const response_html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>body{margin:0;background:#f4f6f8;color:#17202a;font:16px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}.card{max-width:680px;margin:30px auto;background:#fff;border:1px solid #dfe4ea;border-radius:16px;padding:24px;box-shadow:0 8px 28px #17202a14}.ok{color:#18794e}.muted{color:#5d6d7e}.box{background:#f7f9fa;border:1px solid #e5e9ed;border-radius:10px;padding:14px;white-space:pre-wrap}</style></head><body><main class="card"><h1 class="${success ? 'ok' : ''}">${esc(title)}</h1><p>${esc(message)}</p>${success && prepared.decision !== 'SKIP' ? `<div class="box">${esc(prepared.new_proposed_text)}</div>` : ''}<p><strong>Nothing was published to Google.</strong></p><p class="muted">The decision, approver identity, and timestamp are saved in the audit log.</p></main></body></html>`;
  return [{ json: {
    review_id: String(prepared.review_id ?? ''), action: String(prepared.decision ?? ''),
    approver: String(prepared.approver ?? ''), actor_basis: String(prepared.actor_basis ?? ''),
    status_before: String(prepared.original_status ?? ''),
    status_after: success ? String(prepared.next_status ?? '') : String(prepared.original_status ?? ''),
    token_state: success ? 'consumed' : 'reused', result: success ? 'SUCCESS' : 'REJECTED',
    event_type: success ? 'DECISION_RECORDED' : 'DUPLICATE_DECISION_REJECTED',
    detail_code: success ? 'CONDITIONAL_UPDATE_APPLIED' : 'CONDITIONAL_UPDATE_ZERO_ROWS',
    publish_result: 'not_published', http_status, response_html,
  } }];
